    Prod.iInSHBarMulti2DDetectPos2x8[0][7][0]=Prod.iInSHBarCodeDetectPos2x8[0][7]-dMilti2DPitch;
    Prod.iInSHBarMulti2DDetectPos2x8[0][7][1]=Prod.iInSHBarCodeDetectPos2x8[0][7]+dMilti2DPitch;
