    Prod.XOutArm_Fix_Place[2][iOutArmYBase][iOutArmXBase]=Tech.iOutArmFix3X+AutoForm[eFix3]->XStart+LoadForm->BlockXStart-KitPitchX+OutArmOffSet[OutOfsFix3]->GetX()+Prod.iTrayKitStartX;
