                Prod.ZOutArm_Fix_Pick [k][iOutArmYBase][iOutArmXBase]=Tech.iOutArmPlaceFix2Z1-200+OutArmOffSet[OutOfsFix1+k]->GetPickUp();   //Ifor 20161222 (jou) add Fix Pickup Offset
