                Prod.ZOutArm_Fix_Pick [k][iOutArmYBase][iOutArmXBase]=Tech.iOutArmPlaceFixZ1-200+OutArmOffSet[OutOfsFix1+k]->GetPickUp();    //Ifor 20161222 (jou) add Fix Pickup Offset
