                    Prod.ZOutArm_SortShuttle_Place[i][j]=Prod.ZOutArm_SortShuttle_Place[iOutArmYBase][iOutArmXBase]+iTemp+OutArmOffSet[OutOfsSortSht]->GetPlace(i, j);
