        Prod.YInArm_AutoClean_Pick[iInArmYBase][iInArmXBase]=Prod.YInArm_Plate1_Pick[iInArmYBase][iInArmXBase] + TestIF.dAutoClean_YStart - HotPlateForm.YStart+InArmOffSet[iAcOfs]->GetY();

