        Prod.YInArm_AutoClean_Pick[iInArmYBase][iInArmXBase]=Tech.iInArmAutoCleanY-TestIF.dAutoClean_YStart+InArmOffSet[iAcOfs]->GetY()-90;     //kevin 20150827  -50 --> -90
