                Prod.ZInArm_Shuttle2_Place[i][j]=Prod.ZInArm_Shuttle2_Place[iInArmYBase][iInArmXBase]+iTemp+InArmOffSet[InOfsLoader]->GetPlace(i, j);//Ztex 2023.12.20 Add In\Out Arm 16 Z Offset
